import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    barrier=cnt.most_common(2)[1][0] if len(cnt)>1 else None
    # find enclosing color: the one forming loops = least common non-background? use second most common
    bg=cnt.most_common(1)[0][0]
    barrier=[c for c in cnt if c!=bg][0]
    fill=4
    vis=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=barrier and not vis[i][j]: vis[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=barrier and not vis[i][j]: vis[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not vis[ni][nj] and g[ni][nj]!=barrier:
                vis[ni][nj]=True; dq.append((ni,nj))
    return [[fill if (g[i][j]!=barrier and not vis[i][j]) else g[i][j] for j in range(w)] for i in range(h)]

